    async def create_link(
        self,
        *,
        name: str,
        pop_id: str,
        bandwidth_mbps: int,
        region: str | None = None,
        project_id: str | None = None,
        tags: list[str] | None = None,
        connection_id: str | None = None,
        partner_id: str | None = None,
        peer_asn: int | None = None,
        vlan: int | None = None,
        routing_policy_v4_id: str | None = None,
        routing_policy_v6_id: str | None = None,
    ) -> Link:
        """
        Create a link

        Create a link (InterLink session / logical InterLink resource) in a given PoP,
        specifying its various configuration details. Links can either be hosted
        (facilitated by partners' shared physical connections) or self-hosted (for users
        who have purchased a dedicated physical connection).

        Args:
            region: The region you want to target
            project_id: ID of the Project to create the link in. (UUID format)
            name: Name of the link.
            tags: List of tags to apply to the link.
            pop_id: PoP (location) where the link will be created. (UUID format)
            bandwidth_mbps: Desired bandwidth for the link. Must be compatible with
                available link bandwidths and remaining bandwidth capacity of the
                connection.
            connection_id: If set, creates a self-hosted link using this dedicated
                physical connection. As the customer, specify the ID of the physical
                connection you already have for this link. (UUID format) Precisely one
                of connection_id, partner_id can be set.
            partner_id: If set, creates a hosted link on a partner's connection. Specify
                the ID of the chosen partner, who already has a shared connection with
                available bandwidth. (UUID format) Precisely one of connection_id,
                partner_id can be set.
            peer_asn: For self-hosted links we need the peer AS Number to establish BGP
                session. If not given, a default one will be assigned.
            vlan: For self-hosted links only, it is possible to choose the VLAN ID. If
                the VLAN is not available (ie already taken or out of range), an error
                is returned.
            routing_policy_v4_id: If set, attaches this routing policy containing IPv4
                prefixes to the Link. Hence, a BGP IPv4 session will be created. (UUID
                format)
            routing_policy_v6_id: If set, attaches this routing policy containing IPv6
                prefixes to the Link. Hence, a BGP IPv6 session will be created. (UUID
                format)
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/interlink/v1beta1/regions/{region}/links",
                region=self._client.region(region),
            ),
            body={
                "project_id": self._client.project_id(project_id),
                "name": name,
                "tags": tags,
                "pop_id": pop_id,
                "bandwidth_mbps": bandwidth_mbps,
                "connection_id": connection_id,
                "partner_id": partner_id,
                "peer_asn": peer_asn,
                "vlan": vlan,
                "routing_policy_v4_id": routing_policy_v4_id,
                "routing_policy_v6_id": routing_policy_v6_id,
            },
        )
        return Link.model_validate(data)

