    async def create_routing_policy(
        self,
        *,
        name: str,
        region: str | None = None,
        project_id: str | None = None,
        tags: list[str] | None = None,
        prefix_filter_in: list[str] | None = None,
        prefix_filter_out: list[str] | None = None,
        is_ipv6: bool | None = None,
    ) -> RoutingPolicy:
        """
        Create a routing policy

        Create a routing policy. Routing policies allow you to set IP prefix filters to
        define the incoming route announcements to accept from the peer, and the
        outgoing routes to announce to the peer.

        Args:
            region: The region you want to target
            project_id: ID of the Project to create the routing policy in. (UUID format)
            name: Name of the routing policy.
            tags: List of tags to apply to the routing policy.
            prefix_filter_in: IP prefixes to accept from the peer (ranges of route
                announcements to accept). (IP network)
            prefix_filter_out: IP prefix filters to advertise to the peer (ranges of
                routes to advertise). (IP network)
            is_ipv6: IP prefixes version of the routing policy.
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/interlink/v1beta1/regions/{region}/routing-policies",
                region=self._client.region(region),
            ),
            body={
                "project_id": self._client.project_id(project_id),
                "name": name,
                "tags": tags,
                "prefix_filter_in": prefix_filter_in,
                "prefix_filter_out": prefix_filter_out,
                "is_ipv6": is_ipv6,
            },
        )
        return RoutingPolicy.model_validate(data)

    async def get_routing_policy(
        self,
        *,
        routing_policy_id: str,
        region: str | None = None,
    ) -> RoutingPolicy:
        """
        Get routing policy

        Get a routing policy for the given routing policy ID. The response object gives
        information including the policy's name, tags and prefix filters.

        Args:
            region: The region you want to target
            routing_policy_id: ID of the routing policy to get. (UUID format)
        """
        data = await self._client.request_json(
            "GET",
            self._client.path(
                "/interlink/v1beta1/regions/{region}/routing-policies/{routing_policy_id}",
                region=self._client.region(region),
                routing_policy_id=routing_policy_id,
            ),
        )
        return RoutingPolicy.model_validate(data)

    async def update_routing_policy(
        self,
        *,
        routing_policy_id: str,
        region: str | None = None,
        name: str | None = None,
        tags: list[Any] | None = None,
        prefix_filter_in: list[Any] | None = None,
        prefix_filter_out: list[Any] | None = None,
    ) -> RoutingPolicy:
        """
        Update a routing policy

        Update an existing routing policy, specified by its routing policy ID. Its name,
        tags and incoming/outgoing prefix filters can be updated.

        Args:
            region: The region you want to target
            routing_policy_id: ID of the routing policy to update. (UUID format)
            name: Name of the routing policy.
            tags: List of tags to apply to the routing policy.
            prefix_filter_in: IP prefixes to accept from the peer (ranges of route
                announcements to accept).
            prefix_filter_out: IP prefix filters for routes to advertise to the peer
                (ranges of routes to advertise).
        """
        data = await self._client.request_json(
            "PATCH",
            self._client.path(
                "/interlink/v1beta1/regions/{region}/routing-policies/{routing_policy_id}",
                region=self._client.region(region),
                routing_policy_id=routing_policy_id,
            ),
            body={
                "name": name,
                "tags": tags,
                "prefix_filter_in": prefix_filter_in,
                "prefix_filter_out": prefix_filter_out,
            },
        )
        return RoutingPolicy.model_validate(data)

